def allocate(weights,minutes):
    """At least one minute per stage; largest-remainder allocation sums exactly."""
    remain=minutes-len(weights); total=sum(weights)
    raw=[remain*w/total for w in weights]; result=[1+math.floor(x) for x in raw]
    order=sorted(range(len(weights)),key=lambda i:-(raw[i]-math.floor(raw[i])))
    for i in order[:minutes-sum(result)]: result[i]+=1
    return result

def make_plan(topic,goal,prior,minutes):
    if goal not in SCHEMES or prior not in ('new','partial','secure') or not 20<=minutes<=120 or not topic.strip() or len(topic)>160: raise ValueError('Проверьте тему, цель и длительность от 20 до 120 минут.')
    chosen=goal; reason=SCHEMES[goal]['reason']
    if prior=='new' and goal in ('practice','review','discussion','inquiry'):
        chosen='new'; reason='Класс ещё не знаком с основой темы. Сначала рекомендуем объяснение и пробу с поддержкой; исходную схему можно выбрать вручную.'
    elif goal=='new' and prior=='secure':
        chosen='practice'; reason='База уже освоена: предлагаем перенести акцент на применение. Если понятие действительно новое, выберите схему объяснения.'
    plans={}
    for key,schema in SCHEMES.items():
        times=allocate([s['weight'] for s in schema['stages']],minutes)
        plans[key]={**schema,'stages':[{**s,'minutes':t,'activity':s['activity'].replace('{topic}',topic)} for s,t in zip(schema['stages'],times)]}
    openings=[{'id':k,**o,'text':o['text'].replace('{topic}',topic)} for k,o in OPENINGS.items() if chosen in o['goals']]
    return dict(recommended=chosen,reason=reason,plans=plans,openings=openings,sources=SOURCES,all_openings=[{'id':k,**o,'text':o['text'].replace('{topic}',topic)} for k,o in OPENINGS.items()],topic=topic,minutes=minutes)
